package studio.solocamera;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.text.*;import android.view.*;import android.widget.*;import java.io.*;
/** A cover is a separate JPEG; editing the cover never alters the timeline. */
final class EditorCoverDesigner {
 private final EditorActivity a;private final Bitmap source;private final EditorCreatorStore store;private final EditorProject target;private Bitmap logo;private String headline="",font;private int color,ratio;private float y=.72f,size=76,shade=.25f;private boolean showLogo=true,saving;
 EditorCoverDesigner(EditorActivity a,Bitmap source){this.a=a;this.source=source;target=a.creatorProject();store=new EditorCreatorStore(a);org.json.JSONObject brand=store.brand();font=brand.optString("font","font:inter");color=brand.optInt("accent",0xffffc857);String path=brand.optString("logo","");if(!path.isEmpty()){BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=4;logo=BitmapFactory.decodeFile(path,o);}}
 private int dp(int n){return Math.round(n*a.getResources().getDisplayMetrics().density);}
 private TextView label(String text){TextView v=new TextView(a);v.setText(text);v.setTextColor(-1);v.setPadding(0,dp(8),0,dp(4));return v;}
 void show(){Dialog dialog=new Dialog(a);LinearLayout root=new LinearLayout(a);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(14),dp(10),dp(14),dp(8));root.setBackgroundColor(0xff10161f);root.addView(label("Cover & thumbnail designer"));CoverView preview=new CoverView();root.addView(preview,new LinearLayout.LayoutParams(-1,0,1));root.addView(label("Drag the headline. Pinch to resize. Your video stays unchanged."));ScrollView scroll=new ScrollView(a);LinearLayout fields=new LinearLayout(a);fields.setOrientation(LinearLayout.VERTICAL);scroll.addView(fields);root.addView(scroll,new LinearLayout.LayoutParams(-1,dp(245)));EditText text=new EditText(a);text.setTextColor(-1);text.setHint("Cover headline");text.setFilters(new InputFilter[]{new InputFilter.LengthFilter(120)});text.setContentDescription("Cover headline");fields.addView(text);text.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){headline=s.toString();preview.invalidate();}});
 Spinner format=new Spinner(a);format.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"YouTube · 16:9","Reels / Shorts · 9:16","Square · 1:1"}));fields.addView(format);format.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){ratio=i;preview.invalidate();}});
 String[] fonts={"font:inter","font:montserrat","font:poppins","font:bebasneue","font:playfairdisplay","font:lora"};Spinner face=new Spinner(a);face.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"Inter","Montserrat","Poppins","Bebas Neue","Playfair Display","Lora"}));face.setSelection(Math.max(0,java.util.Arrays.asList(fonts).indexOf(font)));face.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){font=fonts[i];preview.invalidate();}});fields.addView(face);
 fields.addView(label("Headline size"));SeekBar textSize=new SeekBar(a);textSize.setMax(128);textSize.setProgress((int)size-32);listen(textSize,value->{size=32+value;preview.invalidate();});fields.addView(textSize);fields.addView(label("Darken background"));SeekBar dark=new SeekBar(a);dark.setMax(80);dark.setProgress(25);listen(dark,value->{shade=value/100f;preview.invalidate();});fields.addView(dark);
 LinearLayout colors=new LinearLayout(a);for(int c:new int[]{-1,0xffffc857,0xff66d4e2,0xffff8b79,0xff8fafff}){Button b=new Button(a);b.setText("●");b.setTextColor(c);b.setContentDescription("Cover text color "+Integer.toHexString(c));b.setOnClickListener(v->{color=c;preview.invalidate();});colors.addView(b,new LinearLayout.LayoutParams(0,dp(44),1));}fields.addView(colors);Switch brand=new Switch(a);brand.setText("Show brand logo");brand.setTextColor(-1);brand.setChecked(true);brand.setEnabled(logo!=null);brand.setOnCheckedChangeListener((v,on)->{showLogo=on;preview.invalidate();});fields.addView(brand);
 LinearLayout actions=new LinearLayout(a);Button cancel=new Button(a);cancel.setText("Cancel");cancel.setOnClickListener(v->{if(!saving)dialog.dismiss();});actions.addView(cancel,new LinearLayout.LayoutParams(0,dp(52),1));Button save=new Button(a);save.setText("Save JPEG");save.setOnClickListener(v->{if(saving)return;saving=true;save.setEnabled(false);int w=ratio==1?1080:ratio==2?1080:1280,h=ratio==1?1920:ratio==2?1080:720;Bitmap result=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);draw(new Canvas(result),w,h);new Thread(()->{Uri uri=null;String error="";try{ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,"SoloCover_"+System.currentTimeMillis()+".jpg");values.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");values.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/SoloCamera/Covers");values.put(MediaStore.Images.Media.IS_PENDING,1);uri=a.getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("Cannot create cover");try(OutputStream out=a.getContentResolver().openOutputStream(uri)){if(out==null||!result.compress(Bitmap.CompressFormat.JPEG,94,out))throw new IOException("Cannot write cover");}ContentValues done=new ContentValues();done.put(MediaStore.Images.Media.IS_PENDING,0);a.getContentResolver().update(uri,done,null,null);}catch(Exception e){error=e.getMessage();if(uri!=null){a.getContentResolver().delete(uri,null,null);uri=null;}}finally{result.recycle();}Uri saved=uri;String failure=error;a.runOnUiThread(()->{saving=false;if(a.isFinishing())return;if(saved==null){save.setEnabled(true);Toast.makeText(a,"Cover failed: "+failure,Toast.LENGTH_LONG).show();return;}if(a.creatorProject()==target){a.creatorCheckpoint();target.coverUri=saved.toString();a.creatorChanged();}dialog.dismiss();Toast.makeText(a,"JPEG saved · Pictures / SoloCamera / Covers",Toast.LENGTH_LONG).show();});},"CoverExport").start();});actions.addView(save,new LinearLayout.LayoutParams(0,dp(52),1));root.addView(actions);dialog.setContentView(root);dialog.setOnDismissListener(d->{source.recycle();if(logo!=null)logo.recycle();});dialog.show();dialog.getWindow().setLayout(-1,-1);}
 private void listen(SeekBar b,java.util.function.IntConsumer action){b.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int p,boolean user){if(user)action.accept(p);}});}
 private void draw(Canvas c,int w,int h){Paint p=new Paint(3);float scale=Math.max(w/(float)source.getWidth(),h/(float)source.getHeight()),bw=source.getWidth()*scale,bh=source.getHeight()*scale;c.drawBitmap(source,null,new RectF((w-bw)/2,(h-bh)/2,(w+bw)/2,(h+bh)/2),p);p.setColor(Color.argb((int)(255*shade),0,0,0));c.drawRect(0,0,w,h,p);EditorProject.Clip title=new EditorProject.Clip("cover:title","Cover",1000);title.textSize=(int)size;title.shadowEnabled=true;title.shadowBlur=5;title.shadowX=title.shadowY=2;EditorTitleGraphics.draw(c,title,headline,w*.07f,h*y,w*.86f,size*w/1080f,h*(1-y)-h*.04f,font,true,color,0);if(showLogo&&logo!=null){p.setAlpha(255);float box=w*.14f,k=box/Math.max(logo.getWidth(),logo.getHeight());c.drawBitmap(logo,null,new RectF(w*.92f-logo.getWidth()*k,h*.06f,w*.92f,h*.06f+logo.getHeight()*k),p);}}
 private final class CoverView extends View {private final ScaleGestureDetector pinch;private RectF bounds=new RectF();CoverView(){super(a);pinch=new ScaleGestureDetector(a,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector detector){size=Math.max(32,Math.min(160,size*detector.getScaleFactor()));invalidate();return true;}});setContentDescription("Cover preview: drag headline or pinch to resize");}protected void onDraw(Canvas canvas){canvas.drawColor(0xff26313d);float ratioValue=ratio==1?9f/16:ratio==2?1:16f/9;float w=Math.min(getWidth(),getHeight()*ratioValue),h=w/ratioValue;bounds.set((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);canvas.save();canvas.clipRect(bounds);canvas.translate(bounds.left,bounds.top);EditorCoverDesigner.this.draw(canvas,(int)w,(int)h);canvas.restore();}public boolean onTouchEvent(android.view.MotionEvent e){pinch.onTouchEvent(e);if(e.getPointerCount()==1&&(e.getAction()==MotionEvent.ACTION_DOWN||e.getAction()==MotionEvent.ACTION_MOVE)){y=Math.max(.08f,Math.min(.83f,(e.getY()-bounds.top)/Math.max(1,bounds.height())));invalidate();}if(e.getAction()==MotionEvent.ACTION_UP)performClick();return true;}public boolean performClick(){super.performClick();return true;}}
}
